-- Own structured course progress; Auth subjects have no editorial User relation.
CREATE TABLE "watch_learning_progress" ("id" TEXT NOT NULL, "user_id" TEXT NOT NULL, "course_id" TEXT NOT NULL, "content_version" TEXT NOT NULL, "lesson_id" TEXT NOT NULL, "completed_movement_ids" TEXT[] DEFAULT ARRAY[]::TEXT[], "completed_step_ids" TEXT[] DEFAULT ARRAY[]::TEXT[], "completed_at" TIMESTAMP(3), "resume_card_id" TEXT, "revision" INTEGER NOT NULL DEFAULT 1, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "watch_learning_progress_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "watch_learning_progress_subject_course_version_lesson_key" ON "watch_learning_progress"("user_id", "course_id", "content_version", "lesson_id");
CREATE TABLE "watch_learning_erasures" ("subject_hash" TEXT NOT NULL, "erased_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "watch_learning_erasures_pkey" PRIMARY KEY ("subject_hash"));
